"""Profe's capability registry: the single source of truth for what Profe can do in the app by voice or text.
Built into index.html as <script type="application/json" id="pv-registry"> and checked by tools/profe_check.js.
Every route in route() and every data-act in the app must appear here (as an action, or with voice status pending/unsuitable).
Patterns are regular expressions applied to normalised text (lower case, no accents or punctuation, politeness removed).
{OPEN} = an optional "open / show / go to / abre / ve a / llévame a …" lead-in; {LV} = a level; {ORD} = an ordinal or letter;
{TOPIC} = a guide topic; {PAPER} = an exam paper."""
import json, sys
A = []
def act(id, feature, purpose, en, es, match, route=None, act=None, when=None, params=None, confirm=False, verify="", test="sH", voice="complete", bare=False):
    A.append(dict(id=id, feature=feature, purpose=purpose, en=en, es=es, match=match, route=route, act=act, when=when, params=params or [], confirm=confirm, verify=verify, test=test, voice=voice, bare=bare))
NAV = "hash changes to the route and the page renders"
